public static void main(Args _args)
{
    RMarketAccount account;
    RMarketMethodInterface_GetApiKeyInfo apiMethod;

    Dialog dialog;
    DialogField dlgAccountId;

    dialog = new Dialog("Test API key");
    dlgAccountId = dialog.addFieldValue(extendedTypeStr(RMarketAccountId), 'DAT-ACC00011');

    if (dialog.run())
    {
        account = RMarketAccount::find(dlgAccountId.value());

        if (!account.RecId)
            throw error("Account not found.");

        apiMethod = RMarketMethodInterface::createMethod_GetApiKeyInfo(account.RMarketTable());

        apiMethod.setApiKey(account.RMarketApiKey());
        apiMethod.execute();

        info(strFmt("Account: %1", account.AccountId));
        info(strFmt("Exchange UID: %1", apiMethod.getExchangeUid()));
        info(strFmt("Parent UID: %1", apiMethod.getParentUid()));
        info(strFmt("Is master: %1", apiMethod.isMaster()));
        info(strFmt("Read-only: %1", apiMethod.isReadOnly()));
        info(strFmt("Expires: %1", apiMethod.getExpirationDateTime()));
    }
}
